{
  "hechos": [
    {
      "id": "H1",
      "texto": "La distribución de agua en la zona urbana de San Aurelio fue interrumpida por orden del acueducto.",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H2",
      "texto": "El acueducto de San Aurelio suspendió el suministro de agua potable en todo el casco urbano.",
      "paginas": ["P2", "P4", "P5", "P6"]
    },
    {
      "id": "H3",
      "texto": "Las pruebas de laboratorio hechas en la planta El Retiro mostraron mercurio en concentraciones superiores a la norma.",
      "paginas": ["P2", "P4", "P5", "P6"]
    },
    {
      "id": "H4",
      "texto": "Según los análisis, en la planta El Retiro se encontraron niveles de mercurio por encima del límite permitido.",
      "paginas": ["P1", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H5",
      "texto": "La situación sigue en desarrollo.",
      "paginas": ["P1", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H6",
      "texto": "El servicio no se restablecerá antes de 72 horas.",
      "paginas": ["P2", "P4", "P6"]
    },
    {
      "id": "H7",
      "texto": "La reconexión tardaría como mínimo 72 horas.",
      "paginas": ["P1", "P6"]
    },
    {
      "id": "H8",
      "texto": "Alrededor de 18.000 suscriptores se ven afectados por el corte.",
      "paginas": ["P1", "P2", "P4", "P5", "P6"]
    },
    {
      "id": "H9",
      "texto": "Un funcionario que pidió no ser identificado aseguró que el problema se conocía desde hace un mes.",
      "paginas": ["P1", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H10",
      "texto": "Gloria Avendaño, habitante del barrio San José, contó a Noticias al Instante que varias familias están recogiendo agua lluvia en baldes.",
      "paginas": ["P4"]
    },
    {
      "id": "H11",
      "texto": "Fabio Quintero, líder comunal del barrio Las Acacias, contó a InfoExprés que los colegios enviaron a los estudiantes a casa antes del mediodía.",
      "paginas": ["P5"]
    },
    {
      "id": "H12",
      "texto": "Andrés Salcedo, comerciante del barrio Los Almendros, contó a Alerta Nacional Ya que los colegios enviaron a los estudiantes a casa antes del mediodía.",
      "paginas": ["P6"]
    },
    {
      "id": "H13",
      "texto": "En el barrio El Prado, la junta de acción comunal contó 207 hogares sin agua.",
      "paginas": ["P4"]
    },
    {
      "id": "H14",
      "texto": "En el barrio La Floresta, la junta de acción comunal contó 45 hogares sin agua.",
      "paginas": ["P5"]
    },
    {
      "id": "H15",
      "texto": "En el barrio El Bosque, la junta de acción comunal contó 271 hogares sin agua.",
      "paginas": ["P1"]
    },
    {
      "id": "H16",
      "texto": "En el barrio Las Brisas, la junta de acción comunal contó 479 hogares sin agua.",
      "paginas": ["P3"]
    },
    {
      "id": "H17",
      "texto": "En el barrio Villa Nueva, la junta de acción comunal contó 459 hogares sin agua.",
      "paginas": ["P6"]
    }
  ]
}
